	constraints []*flipt.Constraint
}

func (s *testStore) ListFlags(_ context.Context, _ ...storage.QueryOption) ([]*flipt.Flag, error) { return s.flags, nil }
func (s *testStore) ListRules(_ context.Context, _ string, _ ...storage.QueryOption) ([]*flipt.Rule, error) { return s.rules, nil }
func (s *testStore) ListSegments(_ context.Context, _ ...storage.QueryOption) ([]*flipt.Segment, error) { return s.segments, nil }
func (s *testStore) CreateFlag(_ context.Context, r *flipt.CreateFlagRequest) (*flipt.Flag, error) {
