	s.distributions = append(s.distributions,d)
	for _, rule := range s.rules { if rule.Id == r.RuleId { rule.Distributions = append(rule.Distributions,d) } }
	return d,nil
}

func TestImportExportAttachments(t *testing.T) {
	input := "'`flags:
+- key: feature
+  name: Feature
+  enabled: true
+  variants:
+  - key: treatment
+    attachment:
+      items: [true, 3, null, {nested: [a, 2.5]}]
+      5: value
+  - key: control
+  rules:
+  - segment: audience
+    rank: 1
+    distributions:
+    - variant: treatment
+      rollout: 75
+segments:
+- key: audience
+  constraints:
+  - type: STRING_COMPARISON_TYPE
+    property: country
+    operator: eq
+    value: US
+`
	store := new(testStore)
	if err := NewImporter(store).Import(context.Background(), strings.NewReader(input)); err != nil { t.Fatal(err) }
	if len(store.flags)!=1 || len(store.variants)!=2 || len(store.segments)!=1 || len(store.constraints)!=1 || len(store.rules)!=1 || len(store.distributions)!=1 { t.Fatal("missing imported entities") }
	if store.variants[1].Attachment != "" { t.Fatalf("missing attachment became %q", store.variants[1].Attachment) }
	var attachment interface{}
	if err := json.Unmarshal([]byte(store.variants[0].Attachment), &attachment); err != nil { t.Fatal(err) }
	expected := map[string]interface{}{"items": []interface{}{true,float64(3),nil,map[string]interface{}{"nested": []interface{}{"a",float64(2.5)}}}, "5":"value"}
	if !reflect.DeepEqual(attachment,expected) { t.Fatalf("attachment = %#v",attachment) }
	var out bytes.Buffer
	if err := NewExporter(store).Export(context.Background(), &out); err != nil { t.Fatal(err) }
	var doc Document
	if err := yaml.Unmarshal(out.Bytes(), &doc); err != nil { t.Fatal(err) }
	if _, ok := doc.Flags[0].Variants[0].Attachment.(map[interface{}]interface{}); !ok { t.Fatalf("attachment was not a YAML map: %T",doc.Flags[0].Variants[0].Attachment) }
	if len(doc.Flags[0].Rules)!=1 || len(doc.Flags[0].Rules[0].Distributions)!=1 || doc.Flags[0].Rules[0].Distributions[0].VariantKey!="treatment" { t.Fatal("rule distribution not exported") }
	if len(doc.Segments)!=1 || len(doc.Segments[0].Constraints)!=1 { t.Fatal("segment constraint not exported") }
	if doc.Flags[0].Variants[1].Attachment != nil { t.Fatal("missing attachment appeared in export") }
}
